using Microsoft.Extensions.Options;using TradingSystem.Binance.Execution;using TradingSystem.Binance.Exchange;using TradingSystem.Binance.Orders.Contracts;using TradingSystem.Binance.Resilience;using TradingSystem.Domain.Enums;using TradingSystem.Domain.Positions;
namespace StrategyService.Bots.Bot8015;public sealed record CreatedStop3Order(string AlgoOrderId, string ClientAlgoId, string? Status, decimal TriggerPrice);
public sealed class Bot8015Stop3OrderService(IOptions<Bot8015Options> options, IBinanceFuturesOrderClient orders, BinanceExchangeInfoService exchange, BinanceRetryService retry){readonly Bot8015Options o = options.Value;public Task<CreatedStop3Order> CreateInitialAsync(BotPosition p, decimal q, CancellationToken ct) => CreateWithFallback(p, q, BinanceClientOrderId.Create(o.BotName, "S3", p.ShortId), ct);public async Task<CreatedStop3Order> CreateTrailingAsync(BotPosition p, decimal trigger, int seq, CancellationToken ct) => await Create(p, await exchange.RoundQuantityAsync(p.Symbol, p.RemainingQuantity, ct), await exchange.RoundPriceAsync(p.Symbol, trigger, ct), BinanceClientOrderId.Create(o.BotName, "S3", p.ShortId, seq), ct);async Task<CreatedStop3Order> CreateWithFallback(BotPosition p, decimal q, string id, CancellationToken ct){if(p.EntryPrice is null)throw new InvalidOperationException("EntryPrice is required.");q = await exchange.RoundQuantityAsync(p.Symbol, q, ct);var primary = await exchange.RoundPriceAsync(p.Symbol, p.Side==PositionSide.Long?p.EntryPrice.Value+o.Stop3EntryOffset:p.EntryPrice.Value-o.Stop3EntryOffset, ct);try{return await Create(p, q, primary, id, ct);}catch{return await Create(p, q, await exchange.RoundPriceAsync(p.Symbol, p.EntryPrice.Value, ct), id, ct);}}async Task<CreatedStop3Order> Create(BotPosition p, decimal q, decimal price, string id, CancellationToken ct){if(q<=0)throw new InvalidOperationException("STOP3 quantity is invalid.");var x = await retry.ExecuteAsync("BOT8015_STOP3", c => orders.PlaceStopMarketAlgoOrderAsync(p.Symbol, BinanceOrderSide.Close(p.Side), BinanceOrderSide.Position(p.Side), q, price, id, c), ct);return new(x.AlgoOrderId, id, x.Status, price);}}
